text:
& richlistitem {
  padding: 0.3em;
  padding-inline-start: 12px;
  margin: 0;
  border: none;
  border-radius: 0;
  background-image: none;

  &:hover {
    color: var(--text-color-list-item-hover);
    background-color: var(--background-color-list-item-hover);
  }

  &[selected] {
    background-color: var(--color-accent-primary-selected-unfocused);
    color: inherit;
  }
}

&:focus {
  & > richlistitem[selected] {
    background-color: var(--selected-item-color);
    color: var(--selected-item-text-color) !important;
  }
